"""Stage playbooks 9-12."""
from sections_a import table

def stages():
    S = []
    S.append(dict(n=9, title="Work Out Cost and Price", phase="Launch", gate="G9 – Cost & Price Approved", time="1–2 weeks",
      goal="Know what the product truly costs to build and run, and set a price that leaves a profit after every cost.",
      start="G6 signed (hours known) – can start earlier with estimates.", who="Owner / Finance (owns) · Tech Lead (usage numbers) · DevOps (provider prices) · Sales (price feedback)",
      tools="Cost & Pricing workbook (Appendix B is a worked example), provider pricing pages and calculators", skills="Basic spreadsheet formulas.",
      steps=[
       ("Collect the hours","From timesheets get hours per role and activity. For future products estimate three numbers: optimistic (O), most likely (M), pessimistic (P). Expected = (O + 4M + P) ÷ 6.","Hours table"),
       ("Calculate development labour","Labour cost = hours × <b>fully loaded hourly rate</b> of that role (pay + employer costs + equipment + software seats + office, divided by productive hours). Include founder time. Show optimistic, expected, pessimistic totals.","Labour table (Appendix B.1)"),
       ("List one-time setup costs","Domain, legal documents, payment-gateway onboarding, trademark, penetration test. Mark each <b>Mandatory</b> or <b>Optional</b>. One-time is never mixed with monthly.","Setup table"),
       ("List every monthly cost","Domain (annual ÷ 12), hosting, database, storage, CDN, email, SMS/WhatsApp, authentication, outside APIs, AI services, monitoring, backups, security tools, payment fees, maintenance hours, support hours, miscellaneous.","Monthly cost table"),
       ("Get real prices from official pages","For each provider open its <b>official pricing page or calculator</b>; copy plan, unit, price, currency, region and <b>date visited</b> into the Source column. If you cannot get a price, write ASSUMPTION in red. <b>Never guess.</b> Free tiers can change; never treat them as permanent.","Price list with links and dates"),
       ("Write the usage assumptions","Registered users → monthly active (MAU) → daily active (DAU) → requests per user per day → peak requests per second → storage per user → bandwidth → emails/messages. Use low/medium/high if you have no data.","Assumption table"),
       ("Find the real bottleneck","For 10, 50, 100, 500, 1,000, 5,000 and 10,000 users compare the load with plan limits (requests/second, database size, bandwidth). Cost the first limit you hit. Do <b>not</b> just multiply by number of users.","Capacity table"),
       ("Cost three architectures","<b>Lean</b> (low cost MVP), <b>Professional</b> (paid, backups, monitoring), <b>Scalable</b> (redundancy, scaling). For each give setup, monthly, maintenance, annual, capacity, limits, risks and when to upgrade.","Three-model table"),
       ("Compute totals with the standard formulas","One-time = research + design + development + testing + setup + deployment + legal. Monthly operating = hosting + database + storage + bandwidth + APIs + email + monitoring + backups + maintenance + support + other. Annual = monthly × 12. <b>First-year = one-time + annual.</b> Count shared company costs once; allocate by time share.","Totals box"),
       ("Set the price three ways","<b>Cost-based</b>: (cost to serve + fixed share) ÷ (1 − margin). <b>Competitor-based</b>: position inside the range from your Stage 1 sheet. <b>Value-based</b>: a fair share of the saving the customer gets. Choose a price inside all three.","Price reasoning page"),
       ("Define the plans","Starter, Professional, Business, Enterprise (and a Free Trial if suitable). For each: monthly price, annual price, users, storage, API limit, features, support level, overage charge, upgrade rule. Never promise 'unlimited' without a cost and abuse limit.","Plan table"),
       ("Check profit, not revenue","Compute: contribution per customer = price − refunds − failed payments − gateway fee − variable delivery cost − support. <b>Break-even customers = fixed monthly cost ÷ contribution</b> (round up). Also CAC, LTV = contribution ÷ churn, LTV:CAC (target ≥ 3), payback (target &lt; 12 months). Show tax separately; GST collected is not revenue.","Break-even and profit table"),
       ("Review and request G9","Present to the Owner. Mark every figure as <b>Measured</b> or <b>Assumption</b>. Update the model whenever scope or provider prices change.","G9 signed")],
      selfcheck=["Every price has a link and date or is marked ASSUMPTION","One-time and monthly costs are separate","Maintenance and support labour included","Shared costs counted once","Capacity bottleneck identified","LTV:CAC ≥ 3 and payback &lt; 12 months","Profit shown after all costs; tax shown separately"],
      signoff="Owner and Finance sign G9. Prices are published only after G9.",
      errors=[("Quoting only domain + hosting","Include labour, support, maintenance, payment fees, legal"),("Using a competitor's price blindly","Triangulate with cost and value"),("Forgetting refunds, failed payments, GST","Use leakage factors; GST is pass-through")],
      example="SlotWise worked example (Appendix B): expected development labour ₹10,88,000; break-even 28 paying clinics.",
      learn=[("AWS Pricing Calculator","https://calculator.aws/"),("Vercel pricing","https://vercel.com/pricing"),("Cloudflare plans","https://www.cloudflare.com/plans/"),("CBIC GST","https://cbic-gst.gov.in/")]))
    dns = table(["Record","What it does (simple)","Rule"],[("A / AAAA","Points a name to a server's IPv4 / IPv6 address","Copy exact value from the host"),("CNAME","'This name is an alias of that name'","Cannot sit beside other records on the same name"),("MX","Where email for the domain is delivered","Copy from the email provider; never overwrite existing MX"),("TXT","Text proofs: ownership, SPF, DKIM, DMARC","Only one SPF record per domain"),("SPF","Which servers may send your email","Start from the provider's include value"),("DKIM","Digital signature on your emails","Publish selector exactly as given"),("DMARC","What receivers do with unauthenticated mail","Start with p=none + reports, tighten after review"),("CAA","Which companies may issue certificates","Must include your host's CA")])
    S.append(dict(n=10, title="Put It Online", phase="Launch", gate="G10 – Go-Live Approved", time="2–4 days",
      goal="Take the tested product from the repository to a real address, safely, with monitoring and a way back.",
      start="G7, G8 and G9 are signed.", who="DevOps (executes) · Tech Lead (verifies) · Owner (owns accounts, approves go-live)",
      tools="Registrar, hosting platform, DNS panel, terminal (dig, curl), uptime monitor, error tracker", skills="Stage 5 complete; patience with details.",
      steps=[
       ("Choose and check domain names","Make 5–10 ideas. Search each at 2–3 reputable registrars to see <b>real</b> availability and compare first-year and renewal prices. Search trademark databases for conflicts. Never tell the customer a name is available until you checked that day.","Domain shortlist with prices and dates"),
       ("Register in the company's name","Use the company account (not personal). Turn on MFA, auto-renew, registrar lock and privacy. Record: registrar, owner, renewal date, recovery method, who has access. Put the renewal date in a shared calendar with a 60-day reminder.","Domain/DNS Report started"),
       ("Create the production environment","On the hosting platform create the production project, database, file storage; enter production secrets in the platform's secret settings (not in code). Production uses its own database, never staging's.","Environment ready; secrets stored"),
       ("Deploy to staging first and verify","Connect the repository, set build settings, deploy to staging, open it and run the smoke test list (below).","Staging passes smoke tests"),
       ("Run database migrations on production","Back up first, then run migrations through the pipeline, never by hand editing tables.","Migration log"),
       ("Add the domain on the host and copy exact DNS records","In the host's domain settings add your domain. The host shows <b>the exact records</b> to create. Copy them character by character. Never invent a value. Before changing anything, export or screenshot the existing DNS zone so email records are preserved.","Screenshot of current zone + required records"),
       ("Create the records at your DNS provider","Add the records the host gave you. Lower the TTL (e.g. 300 seconds) a day before the change so mistakes fix quickly.","Records saved"),
       ("Check DNS propagation","In a terminal: <code>dig +short example.com A</code>, <code>dig +short www.example.com CNAME</code>, <code>dig +short example.com MX</code>, <code>dig +short example.com TXT</code>. Compare with what you entered. Propagation can take minutes to hours.","Command outputs saved"),
       ("Confirm HTTPS and redirect","The host issues the certificate automatically after DNS works. Check <code>curl -I http://example.com</code> shows a redirect (301/308) to https, and <code>curl -I https://example.com</code> shows 200.","curl outputs saved"),
       ("Set up email authentication","Add SPF, DKIM and DMARC as given by your email provider. Send a test to a mailbox and view 'original message' to confirm SPF, DKIM and DMARC say <b>pass</b>.","Headers show pass"),
       ("Switch on backups, monitoring, error tracking and alerts","Daily database backup with a tested restore; uptime check every 1–5 minutes from two places; error tracker connected; alerts go to the on-call person's phone and email.","Test alert received"),
       ("Run production smoke tests (15 minutes)","Sign up, log in, create and read the main record, pay with a test card then one real small payment and refund it, receive an email, export a file, log out. Any failure = stop and fix.","Smoke test sheet all green"),
       ("Test the rollback","On staging redeploy the previous version and reverse the last migration in under 15 minutes. Record the exact steps.","Rollback evidence"),
       ("Complete the Deployment Report and request G10","Fill the template with: version, date, who deployed, env settings (names only), test results, rollback proof. Owner approves go-live.","G10 signed")],
      selfcheck=["Domain owned by the company with MFA and auto-renew","Existing email records preserved","DNS values exactly match the host's instructions","HTTPS valid; HTTP redirects to HTTPS","SPF, DKIM, DMARC pass","Backup restore tested","Alerts reach a real person","Smoke tests green; rollback proven"],
      signoff="Tech Lead verifies; Owner signs G10. Never go live on a Friday evening.",
      extra="<h4>DNS records in plain English</h4>"+dns,
      errors=[("Overwrote MX records and email stopped","Always export the zone first; restore the saved MX records"),("Certificate not issued","DNS is wrong or not propagated yet; re-check records and wait"),("Registered in an employee's personal account","Transfer to the company account immediately")],
      example="SlotWise: domain registered, DNS verified with dig, HTTPS redirect confirmed, rollback tested in 9 minutes; G10 signed on a Tuesday morning.",
      learn=[("Cloudflare: what is DNS","https://www.cloudflare.com/learning/dns/what-is-dns/"),("ICANN","https://www.icann.org/"),("Vercel domains","https://vercel.com/docs/domains")]))
    S.append(dict(n=11, title="Show, Sell and Deliver", phase="Launch", gate="G11 – Customer Acceptance", time="2–8 weeks per customer",
      goal="Win paying customers honestly, onboard them well and hand the product over with written acceptance.",
      start="Staging or production demo is stable; G9 signed (price known).", who="Sales Lead · Product Owner · Support Lead · Owner (approves terms) · Legal adviser",
      tools="Demo environment with fake data, proposal and SOW templates, e-signature, CRM/pipeline in the dashboard", skills="Clear speaking; honesty about limits.",
      steps=[
       ("Prepare demo data","Create a clean demo account with <b>fake or written-authorised data</b>. Never show real customer data.","Demo account ready"),
       ("Write the demo script (25 minutes)","1 Introduction · 2 Their problem · 3 How they do it today · 4 Our solution · 5 Live workflow · 6 Benefits · 7 <b>Limitations (say them honestly)</b> · 8 Pricing · 9 Pilot proposal · 10 Next steps. Show only finished features.","Script"),
       ("Rehearse and record","Practise twice with a colleague; fix anything that fails. Keep a screen recording as backup.","Rehearsal done"),
       ("Find and qualify leads","Use your ICP from Stage 1. A good lead has the problem, budget, a decision-maker and a reason to act now. Log every lead in the pipeline with next action and date.","Pipeline updated"),
       ("Hold a discovery call","Listen first: current process, pain, volume, budget, decision process, timeline. Write notes within 24 hours.","Discovery notes"),
       ("Give the demo","Follow the script; ask for questions; note objections.","Demo notes"),
       ("Send the proposal and Statement of Work","Proposal: problem, solution, price, timeline. SOW: exact scope, deliverables, acceptance criteria, timeline, responsibilities, fees. Legal adviser reviews contract terms: ownership of code and reusable components, third-party licences, customer data ownership, confidentiality, liability, termination, data export, support hours.","Documents sent; Owner approved terms"),
       ("Run the pilot","30–60 days with 2–3 success measures agreed in writing; weekly check-ins; fix issues quickly.","Pilot report"),
       ("Onboard the customer","Create their tenant, import data, set roles, train users (e.g. 2 × 90 minutes), hand over the <b>user manual</b> and <b>admin manual</b>, share support contacts and hours.","Onboarding checklist"),
       ("Get written acceptance","The customer signs the Acceptance Form confirming the SOW criteria are met. Issue the invoice per the agreement.","Signed acceptance"),
       ("Handover pack","Manuals, training slides, support process, escalation contacts, subscription terms, renewal date. Ask permission in writing before using their name, logo, screenshot or quote anywhere.","G11 signed")],
      selfcheck=["No unfinished feature was shown as finished","Demo used fake or authorised data","Contract defines ownership of code, data and IP","Pilot measures written and met","Customer signed acceptance","Written consent held before any logo or testimonial use"],
      signoff="Customer signs acceptance; Owner signs G11.",
      errors=[("Promising future features","Say 'not available today' and offer a Change Request"),("Verbal scope agreements","Put everything in the SOW"),("Using real data in a demo","Use fake data or get written authorisation")],
      example="SlotWise: 3 clinics piloted for 60 days at an agreed pilot price; all 3 signed acceptance; 2 converted to annual plans.",
      learn=[("MeitY","https://www.meity.gov.in/")]))
    S.append(dict(n=12, title="Keep It Running", phase="Operate", gate="G12 – Operations Accepted", time="Ongoing",
      goal="Keep the service up, secure, supported and profitable, because subscriptions only continue if the product works every day.",
      start="Product is live (G10) and customers are onboarded.", who="Support Lead · DevOps · Tech Lead (incident commander) · Owner (reviews monthly)",
      tools="Uptime monitor, error tracker, logs, ticket system, status page, dashboard", skills="Calm communication; reading logs.",
      steps=[
       ("Daily (15 min)","Check the dashboard: uptime, errors, backup success, new tickets. Reply to every new ticket (first response target agreed in the contract).","Daily check ticked"),
       ("Weekly (1 hour)","Review error trends, slow pages, failed payments, expiring certificates/domains; plan patches; update the board.","Weekly note"),
       ("Monthly: patch and update","Update dependencies and apply security patches on staging, test, then deploy through the pipeline.","Patch list"),
       ("Monthly: restore drill","Restore the latest backup to staging and compare data. Record time taken.","Drill evidence"),
       ("Monthly: cost and usage review","Compare real invoices with the cost model; check usage vs plan limits; flag customers near limits for upgrade; update the model.","Cost review sheet"),
       ("Monthly: subscriptions and billing","Check renewals due, failed payments, refunds, churn; contact at-risk customers; confirm invoices and GST records with the accountant.","MRR, churn, renewals sheet"),
       ("Handle support tickets","Acknowledge → classify severity → fix or workaround → confirm with customer → close with notes. Repeated questions become help articles.","Ticket history"),
       ("Handle incidents using the matrix","<b>Critical</b>: service down or serious security incident – Tech Lead leads, tell the Owner at once, post status update, fix or roll back, review within 5 days. <b>High</b>: major feature unavailable. <b>Medium</b>: limited impact, workaround exists. <b>Low</b>: cosmetic. Each incident gets an owner, updates to customers, and a written post-incident review.","Incident report"),
       ("Handle feature requests","Never build them straight away: log them, the PO scores value/effort, accepted ones go through Change Request or the next release plan.","Request log"),
       ("Write the monthly Maintenance Report","Uptime, incidents, patches, backup drill, cost vs plan, support statistics, customer satisfaction, next month's actions. Send to Owner and customer if contracted.","Report saved in 10-maintenance"),
       ("Review the service promise","Never promise an SLA (uptime or response time) the team cannot staff and monitor. Review quarterly.","G12 signed")],
      selfcheck=["Monitoring and alerts are working","Backups restored this month","Patches applied within the agreed window","Costs compared with the model","Incidents all have reports","Nothing promised that we cannot deliver"],
      signoff="Tech Lead signs G12 when runbooks, on-call and monitoring exist; Owner reviews monthly.",
      extra="<h4>Incident levels</h4>"+table(["Level","Meaning","Owner","First response (example)","Customer message"],[("Critical","Service down or confirmed serious security incident","Tech Lead","≤ 30 min if 24×7 is staffed","Status page + email at once, update every hour"),("High","Major function unavailable","DevOps on call","≤ 2 working hours","Email, update every 4 hours"),("Medium","Limited function, workaround exists","Support → Developer","≤ 1 working day","Ticket updates"),("Low","Minor or cosmetic","Support Lead","≤ 3 working days","Ticket")])+"<p class='note'>Example response times only. Publish a target only if staffing and monitoring can meet it.</p>",
      errors=[("Fixing production directly","Always use the pipeline; hotfix branch + review even when urgent"),("No one watches alerts","Define an on-call rota with phone numbers"),("Silent outage","Tell customers early; silence destroys trust")],
      example="SlotWise: monthly report shows 99.9% measured uptime, 2 Medium incidents, backup drill 22 minutes, infrastructure cost 6% under plan.",
      learn=[("Google SRE book","https://sre.google/sre-book/table-of-contents/"),("NIST SSDF","https://csrc.nist.gov/pubs/sp/800/218/final")]))
    return S
